// PREVIEW (live-wall compositor): the wall's state = main's real engine
// (engine/germinal-engine.js, generated byte-identical from app.html) + the
// compositor (lib/patch.js). Runs in a Worker (engine/wall-worker.js) or, if
// module workers are unavailable, in the page. Returns RGBA frames only; the
// page does the display-only pixel dissolve.
import { createGerminalEngine } from '../engine/germinal-engine.js';
import { Compositor, MAX_AGE_H } from './patch.js';

export class WallCore{
  constructor({ theme = 'love', flags = {}, params = {}, Math: M } = {}){
    this.E = createGerminalEngine({ theme, Math: M }); this.opts = { flags, params }; this.C = null;
  }
  // cellData: the theme's live canvas (RGB555 save) or null → main's start canvas (initCells + 30 fast steps, as quickStart)
  boot({ cellData = null, lastUpdated = null, patches = [], now = Date.now() }){
    const E = this.E;
    if(!(cellData && E.decodeFromServer(cellData))){ E.initCells(); for(let k = 0; k < 30; k++) E.stepGenFast(); }
    this.C = new Compositor(E, this.opts);
    const t0 = Date.parse(lastUpdated || '') || now;
    this.C.addBase(Math.min(t0, now));
    this.addPatches(patches, now, false);
    this.C.decay(now);
    return this.frame();
  }
  // replay (live=false): each lands at its own created time; live: lands now (a demo clock may run fast)
  addPatches(list, now, live = true){
    const horizon = now - MAX_AGE_H * 3600e3;
    for(const r of (list || []).slice().sort((a, b) => Date.parse(a.created) - Date.parse(b.created))){
      const t = live ? now : Math.min(now, Date.parse(r.created) || now);
      if(!live && t < horizon) continue;
      this.C.decay(t); this.C.land(r, t);
    }
    this.C.decay(now);
    return this.frame();
  }
  // one wall Evolve: fade/caps first, then main's real stepGen, unchanged
  step(now){ this.C.decay(now); this.C.safeguards(now); this.E.stepGen(); return this.frame(); }
  frame(){
    const cells = this.E.cells, n = this.E.WT, rgba = new Uint8ClampedArray(n * 4);
    for(let i = 0, o = 0; i < n; i++, o += 4){ const c = cells[i].c || '#000000';
      if(c.length >= 7){ rgba[o] = parseInt(c.slice(1, 3), 16); rgba[o + 1] = parseInt(c.slice(3, 5), 16); rgba[o + 2] = parseInt(c.slice(5, 7), 16); }
      else { rgba[o] = parseInt(c[1] + c[1], 16) || 0; rgba[o + 1] = parseInt(c[2] + c[2], 16) || 0; rgba[o + 2] = parseInt(c[3] + c[3], 16) || 0; }
      rgba[o + 3] = 255; }
    return { rgba, stats: this.C ? this.C.summary() : null, generation: this.E.generation };
  }
}
